<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gallery — {{ $siteName }}</title><style>:root{--bg:#03090e;--text:#effcff;--muted:#91aeb8;--line:rgba(93,211,238,.16);--cyan:#4fd2ee}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#020a10,#061721 55%,#020a10);color:var(--text);font-family:Inter,system-ui,sans-serif}.shell{width:min(1180px,calc(100% - 28px));margin:auto}a{color:inherit;text-decoration:none}.top{height:68px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{font-weight:850}.back{font-size:10px;padding:9px 12px;border:1px solid var(--line);border-radius:9px;color:#b7d3da}.hero{padding:58px 0 30px}.eyebrow{font-size:9px;letter-spacing:.2em;color:var(--cyan);text-transform:uppercase}.hero h1{font-size:clamp(40px,6vw,68px);letter-spacing:-.05em;margin:10px 0}.hero p{color:var(--muted);font-size:11px;line-height:1.8}.gallery-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding-bottom:60px}.folder{position:relative;min-height:205px;overflow:hidden;border:1px solid var(--line);border-radius:18px;background:#071923}.folder img{width:100%;height:205px;object-fit:cover;display:block;opacity:.72;transition:.3s}.folder:hover img{transform:scale(1.04);opacity:.9}.folder:after{content:"";position:absolute;inset:42% 0 0;background:linear-gradient(transparent,rgba(1,7,11,.96))}.icon{position:absolute;z-index:2;left:13px;top:13px;padding:8px 10px;border-radius:9px;background:rgba(0,8,12,.7);border:1px solid rgba(255,255,255,.12);color:#a8f5ff}.info{position:absolute;z-index:2;left:15px;right:15px;bottom:13px}.info h2{font-size:15px;margin:0 0 5px}.info p{margin:0;color:#a8c1c8;font-size:9px;line-height:1.6}.empty{grid-column:1/-1;padding:55px;text-align:center;border:1px dashed var(--line);border-radius:18px;color:var(--muted)}@media(max-width:950px){.gallery-grid{grid-template-columns:repeat